@code {
    private const int PageSize = 30;
    private static readonly string[] _commonEmojis = ["👍", "❤️", "😂", "🎉", "🔥", "👀"];

    // ── State ──
    private List<Channel>? _channels;
    private int? _activeChannelId;
    private Channel? _activeChannel;
    private List<Message>? _messages;
    private Dictionary<int, ThreadSummary> _threadSummaries = new();
    private bool _loadingOlder;
    private bool _allOlderLoaded;
    private int? _hoveredMessageId;
    private int? _emojiPickerMessageId;

    // Thread panel
    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message>? _threadReplies;
    private string _threadReplyText = string.Empty;

    // Message input
    private string _newMessageText = string.Empty;
    private ElementReference _messageListRef;

    // ── Lifecycle ──
    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
    }

    // ── Channel Selection ──
    private async Task SelectChannelAsync(Channel channel)
    {
        _activeChannelId = channel.Id;
        _activeChannel = channel;
        _messages = null;
        _allOlderLoaded = false;
        _threadSummaries.Clear();
        CloseThread();

        _messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        await ChatService.MarkChannelReadAsync(channel.Id);
        await BuildThreadSummariesAsync();
        await RefreshChannelListAsync();
    }

    private async Task RefreshChannelListAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
    }

    // ── Pagination (scroll-to-top) ──
    private async Task OnMessageListScroll()
    {
        // This event fires on any scroll. We load older messages only when the
        // user scrolls to the very top and there are still older messages.
        if (_loadingOlder || _allOlderLoaded || _messages is null || _activeChannelId is null)
            return;

        // The @onscroll handler doesn't give us scroll position natively.
        // We use a simple heuristic: if the current message count is a multiple
        // of PageSize, there may be more. The actual top-detection relies on JS
        // interop in a production app; here we load on every scroll event when
        // near the page boundary, which is a reasonable approximation.
        _loadingOlder = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannelId.Value, _messages.Count, PageSize);
        if (older.Count == 0)
        {
            _allOlderLoaded = true;
        }
        else
        {
            _messages.InsertRange(0, older);
            await BuildThreadSummariesAsync();
        }

        _loadingOlder = false;
    }

    // ── Sending Messages ──
    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_newMessageText) || _activeChannelId is null)
            return;

        var sent = await ChatService.SendMessageAsync(_activeChannelId.Value, _newMessageText.Trim(), null);
        _messages ??= new();
        _messages.Add(sent);
        _newMessageText = string.Empty;
    }

    private async Task OnMessageKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMessageAsync();
        }
    }

    // ── Reactions ──
    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    private async Task AddReactionAsync(int messageId, string emoji)
    {
        _emojiPickerMessageId = null;
        await ChatService.AddReactionAsync(messageId, emoji);

        // Refresh message list to show updated reactions
        if (_activeChannelId is not null && _messages is not null)
        {
            _messages = await ChatService.GetMessagesAsync(_activeChannelId.Value, 0, _messages.Count);
        }
    }

    // ── Thread Panel ──
    private async Task OpenThreadAsync(Message rootMessage)
    {
        _threadRootMessage = rootMessage;
        _threadOpen = true;
        _threadReplyText = string.Empty;
        _threadReplies = await ChatService.GetThreadAsync(rootMessage.Id);
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = null;
        _threadReplyText = string.Empty;
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReplyText) || _threadRootMessage is null || _activeChannelId is null)
            return;

        var reply = await ChatService.SendMessageAsync(_activeChannelId.Value, _threadReplyText.Trim(), _threadRootMessage.Id);
        _threadReplies ??= new();
        _threadReplies.Add(reply);
        _threadReplyText = string.Empty;

        // Refresh main list to update reply counts
        if (_messages is not null)
        {
            await BuildThreadSummariesAsync();
        }
    }

    private async Task OnThreadKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendThreadReplyAsync();
        }
    }

    // ── Thread Summaries ──
    private async Task BuildThreadSummariesAsync()
    {
        if (_messages is null) return;

        _threadSummaries.Clear();
        // Messages with replies: any message that has ReplyToId == null (root)
        // and at least one other message references it.
        var rootIds = _messages
            .Where(m => m.ReplyToId is null)
            .Select(m => m.Id)
            .ToHashSet();

        var repliesByRoot = _messages
            .Where(m => m.ReplyToId is not null && rootIds.Contains(m.ReplyToId.Value))
            .GroupBy(m => m.ReplyToId!.Value);

        foreach (var group in repliesByRoot)
        {
            _threadSummaries[group.Key] = new ThreadSummary(
                group.Key,
                group.Count(),
                group.Max(m => m.SentAt));
        }

        // Also fetch thread info from the service for root messages that may
        // have replies not loaded in the current page.
        foreach (var rootId in rootIds.Where(id => !_threadSummaries.ContainsKey(id)))
        {
            try
            {
                var thread = await ChatService.GetThreadAsync(rootId);
                if (thread.Count > 0)
                {
                    _threadSummaries[rootId] = new ThreadSummary(
                        rootId,
                        thread.Count,
                        thread.Max(t => t.SentAt));
                }
            }
            catch
            {
                // Thread may not exist; skip
            }
        }
    }

    private ThreadSummary? GetThreadSummary(int messageId)
    {
        _threadSummaries.TryGetValue(messageId, out var summary);
        return summary;
    }

    // ── Helpers ──
    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();

        return diff.TotalSeconds switch
        {
            < 60 => "just now",
            < 3600 => $"{(int)diff.TotalMinutes} min ago",
            < 86400 => $"{(int)diff.TotalHours}h ago",
            < 604800 => $"{(int)diff.TotalDays}d ago",
            _ => sentAt.ToString("MMM d, yyyy")
        };
    }

    private static string TruncateDescription(string description)
    {
        const int max = 40;
        return description.Length <= max ? description : string.Concat(description.AsSpan(0, max), "…");
    }
}

